export function fixture(){let s=emptyState();const p={...makeProject('Synthetic Production'),id:'production-demo',shotOrder:[]};s.projects=[p];const a={...makeBoard(p.id,'Board A','whiteboard'),id:'board-a'},b={...makeBoard(p.id,'Board B','whiteboard'),id:'board-b'};a.nodes=[makeFrame(40,40,{id:'placement-a',title:'Shared Shot',shot:'S01-SH01'}),makeFrame(440,40,{id:'planning',title:'Planning only'}),makeTextNode(40,520,{id:'text',text:'Synthetic note'}),makeImageNode(440,520,{id:'image',assetId:null})];a.wires=[{id:'wire',fromId:'placement-a',toId:'planning',type:'text',label:'Planning connection'}];s.boards=[a,b];s=promoteFrame(s,a.id,'placement-a','shot-one');s=placeShot(s,b.id,'shot-one','placement-b');s=duplicateShot(s,'shot-one','shot-two');return stateSchema.parse(s);}
